window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-895e9865ac4b9f03"]={"versions": [{"id": "FIG-895e9865ac4b9f03", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm StateMachine</code>) der AUTOSAR Classic Platform für das Modul ADC Driver (MCAL). Das Diagramm modelliert die übergeordneten Lebenszyklus- und Betriebsmodi-Zustände des Treibers sowie die Aufteilung in die Gruppen-Konvertierungsmodi One-Shot und Continuous.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Zustandsdiagramm spezifiziert folgende Zustände und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>ADC_UNINIT</code>: Initialer Zustand nach Systemstart/Reset, in dem der ADC-Treiber nicht initialisiert ist.\n</li><li><code>ADC_INIT</code>: Zusammengesetzter Zustand (Composite State) nach erfolgter Treiberinitialisierung. Er ist orthogonal in zwei Regionen unterteilt: <code>[ONE_SHOT]</code> und <code>[CONTINUOUS]</code>.\n</li><li><code>ONE-SHOT</code>: Sub-Zustandsautomat für ADC-Kanalgruppen im One-Shot-Konvertierungsmodus (mit eigenem Initial-Pseudozustand).\n</li><li><code>CONTINUOUS</code>: Sub-Zustandsautomat für ADC-Kanalgruppen im Continuous-Konvertierungsmodus (mit eigenem Initial-Pseudozustand).\n</li></ul>\n</li><li>Schnittstellen / API-Aufrufe (Transitionstrigger):\n<ul class=\"fig-list\"><li><code>Adc_Init</code>: Überführt den Treiber von <code>ADC_UNINIT</code> nach <code>ADC_INIT</code>.\n</li><li><code>Adc_DeInit</code>: Überführt den Treiber von <code>ADC_INIT</code> zurück nach <code>ADC_UNINIT</code>.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Initialer Startzustand (<code>Reset</code>), der direkt nach <code>ADC_UNINIT</code> führt.\n</li><li>Lokale Initialzustände innerhalb der Regionen <code>[ONE_SHOT]</code> und <code>[CONTINUOUS]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bei Eintritt eines System-Resets (<code>Reset</code>) wechselt der ADC-Treiber über den unkonditionierten Initialübergang in den Zustand <code>ADC_UNINIT</code>.\n</li><li>Durch den Aufruf der API-Funktion <code>Adc_Init</code> wechselt das Modul aus <code>ADC_UNINIT</code> in den Verbundzustand <code>ADC_INIT</code>.\n</li><li>Innerhalb von <code>ADC_INIT</code> führen die lokalen Initialübergänge in die jeweiligen Unterzustände <code>ONE-SHOT</code> bzw. <code>CONTINUOUS</code>.\n</li><li>Der Aufruf der API-Funktion <code>Adc_DeInit</code> beendet den Verbundzustand <code>ADC_INIT</code> und versetzt den ADC-Treiber zurück in den Zustand <code>ADC_UNINIT</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Aufruf von <code>Adc_Init</code> ist Voraussetzung für jegliche Gruppenkonvertierungen.\n</li><li>Eine Re-Initialisierung oder De-Initialisierung über <code>Adc_DeInit</code> darf gemäß AUTOSAR-Vorgaben nur erfolgen, wenn keine Konvertierungen aktiv sind.\n</li><li>Gemäß Kommentar-Note stellen die Zustände <code>ONE-SHOT</code> und <code>CONTINUOUS</code> statische Konfigurationsoptionen für ADC-Kanalgruppen dar: Eine einzelne ADC-Gruppe kann immer nur genau einem der beiden Modi zugeordnet sein (<code>The &#x27;concurrent states&#x27; ONE-SHOT and CONTINUOUS are configuration options for ADC groups. One ADC group can be only in one of the two states.</code>).\n</li><li>Beide Unterzustände sind als Sub-State-Machines modelliert (gekennzeichnet durch das Submachine-Symbol), deren internes dynamisches Konvertierungsverhalten in separaten Zustandsdiagrammen spezifiziert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cdd7519b3b52f953", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm StateMachine</code>) der AUTOSAR Classic Platform für das Modul ADC Driver (MCAL). Das Diagramm modelliert die übergeordneten Lebenszyklus- und Betriebsmodi-Zustände des Treibers sowie die Aufteilung in die Gruppen-Konvertierungsmodi One-Shot und Continuous.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Zustandsdiagramm spezifiziert folgende Zustände und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>ADC_UNINIT</code>: Initialer Zustand nach Systemstart/Reset, in dem der ADC-Treiber nicht initialisiert ist.\n</li><li><code>ADC_INIT</code>: Zusammengesetzter Zustand (Composite State) nach erfolgter Treiberinitialisierung. Er ist orthogonal in zwei Regionen unterteilt: <code>[ONE_SHOT]</code> und <code>[CONTINUOUS]</code>.\n</li><li><code>ONE-SHOT</code>: Sub-Zustandsautomat für ADC-Kanalgruppen im One-Shot-Konvertierungsmodus (mit eigenem Initial-Pseudozustand).\n</li><li><code>CONTINUOUS</code>: Sub-Zustandsautomat für ADC-Kanalgruppen im Continuous-Konvertierungsmodus (mit eigenem Initial-Pseudozustand).\n</li></ul>\n</li><li>Schnittstellen / API-Aufrufe (Transitionstrigger):\n<ul class=\"fig-list\"><li><code>Adc_Init</code>: Überführt den Treiber von <code>ADC_UNINIT</code> nach <code>ADC_INIT</code>.\n</li><li><code>Adc_DeInit</code>: Überführt den Treiber von <code>ADC_INIT</code> zurück nach <code>ADC_UNINIT</code>.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Initialer Startzustand (<code>Reset</code>), der direkt nach <code>ADC_UNINIT</code> führt.\n</li><li>Lokale Initialzustände innerhalb der Regionen <code>[ONE_SHOT]</code> und <code>[CONTINUOUS]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bei Eintritt eines System-Resets (<code>Reset</code>) wechselt der ADC-Treiber über den unkonditionierten Initialübergang in den Zustand <code>ADC_UNINIT</code>.\n</li><li>Durch den Aufruf der API-Funktion <code>Adc_Init</code> wechselt das Modul aus <code>ADC_UNINIT</code> in den Verbundzustand <code>ADC_INIT</code>.\n</li><li>Innerhalb von <code>ADC_INIT</code> führen die lokalen Initialübergänge in die jeweiligen Unterzustände <code>ONE-SHOT</code> bzw. <code>CONTINUOUS</code>.\n</li><li>Der Aufruf der API-Funktion <code>Adc_DeInit</code> beendet den Verbundzustand <code>ADC_INIT</code> und versetzt den ADC-Treiber zurück in den Zustand <code>ADC_UNINIT</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Aufruf von <code>Adc_Init</code> ist Voraussetzung für jegliche Gruppenkonvertierungen.\n</li><li>Eine Re-Initialisierung oder De-Initialisierung über <code>Adc_DeInit</code> darf gemäß AUTOSAR-Vorgaben nur erfolgen, wenn keine Konvertierungen aktiv sind.\n</li><li>Gemäß Kommentar-Note stellen die Zustände <code>ONE-SHOT</code> und <code>CONTINUOUS</code> statische Konfigurationsoptionen für ADC-Kanalgruppen dar: Eine einzelne ADC-Gruppe kann immer nur genau einem der beiden Modi zugeordnet sein (<code>The &#x27;concurrent states&#x27; ONE-SHOT and CONTINUOUS are configuration options for ADC groups. One ADC group can be only in one of the two states.</code>).\n</li><li>Beide Unterzustände sind als Sub-State-Machines modelliert (gekennzeichnet durch das Submachine-Symbol), deren internes dynamisches Konvertierungsverhalten in separaten Zustandsdiagrammen spezifiziert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-895e9865ac4b9f03", "to": "FIG-cdd7519b3b52f953", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
